package dockerfile

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// ErrChanged is returned by WriteIfUnchanged when the file no longer holds what
// the edit was computed from.
var ErrChanged = errors.New("the file changed since it was read")

// WriteIfUnchanged replaces the file at path with updated, provided it still
// holds exactly expected — the content the change was computed from, and the one
// the user was shown and agreed to. Anything else is ErrChanged and the file is
// left alone: the user confirmed *that* diff, not another.
//
// The write goes through a temporary file in the same directory, then a rename,
// so a reader never sees half a file and a failure leaves the original in
// place. The file's permission bits are kept; a symbolic link is followed and
// its target replaced, not the link. The owner is not preserved when the process
// cannot chown, which is the ordinary case.
func WriteIfUnchanged(path string, expected, updated []byte) error {
	target, err := filepath.EvalSymlinks(path)
	if err != nil {
		return err
	}
	current, err := os.ReadFile(target)
	if err != nil {
		return err
	}
	if !bytes.Equal(current, expected) {
		return ErrChanged
	}
	info, err := os.Stat(target)
	if err != nil {
		return err
	}

	tmp, err := os.CreateTemp(filepath.Dir(target), filepath.Base(target)+".devdesk-*")
	if err != nil {
		return err
	}
	name := tmp.Name()
	fail := func(err error) error {
		_ = tmp.Close()
		_ = os.Remove(name)
		return err
	}
	if _, err := tmp.Write(updated); err != nil {
		return fail(fmt.Errorf("write %s: %w", name, err))
	}
	if err := tmp.Chmod(info.Mode().Perm()); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(name)
		return err
	}
	if err := os.Rename(name, target); err != nil {
		_ = os.Remove(name)
		return err
	}
	return nil
}

// Package remediation turns a scan's findings into what can be done about
// them, without any I/O: which vulnerabilities have a fixed version, whether a
// base image or an application dependency has to move, and the command that
// moves it.
//
// Everything here is a function of the findings. Whether a proposed fix
// actually clears the CVEs is not decided here — that is measured by
// re-scanning, never inferred.
package remediation

import (
	"slices"
	"sort"

	"github.com/anthnel/devdesk/internal/scan"
)

// Summary counts the vulnerabilities that have a fixed version, by what has to
// move to clear them.
type Summary struct {
	// BaseImage is fixed by a package upgrade in the image's OS (or a newer
	// base image); Dependencies by bumping an application dependency.
	BaseImage    int
	Dependencies int
	// Unclassified are fixable findings recorded without a class — a result
	// cached before the class was stored. They are counted apart, never as
	// either class, and disappear at the next scan.
	Unclassified int
	// Unfixed are vulnerabilities with no fixed version yet.
	Unfixed int
}

// Fixable is the number of vulnerabilities that have a fixed version.
func (s Summary) Fixable() int { return s.BaseImage + s.Dependencies + s.Unclassified }

// Summarize counts the vulnerabilities in findings. Secrets, licenses,
// misconfigurations and pipeline findings are not vulnerabilities and are
// ignored.
func Summarize(findings []scan.Finding) Summary {
	var s Summary
	for _, f := range findings {
		if scan.Categorize(f) != scan.CategoryVulnerability {
			continue
		}
		if f.FixedIn == "" {
			s.Unfixed++
			continue
		}
		switch f.Class {
		case scan.ClassOSPackages:
			s.BaseImage++
		case scan.ClassLangPackages:
			s.Dependencies++
		default:
			s.Unclassified++
		}
	}
	return s
}

// Fix is one package that has to move, with every CVE moving it clears.
