func TestTheMatchedStringOfASecretNeverLeaves(t *testing.T) {
	const secret = "AKIAIOSFODNN7EXAMPLE-do-not-leak-me"

	fakeCacheHome(t)
	storeImageResult(t, "app:1.0", &scan.Result{
