func TestTheInsertionTouchesNothingElse(t *testing.T) {
	src := "# build it\r\nFROM alpine:3.21\r\nRUN apk add curl\r\nENTRYPOINT [\"/app\"]\r\n"
	got, _ := apply(t, src, misconf("AVD-DS-0002", "Dockerfile"))
